INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Authentifizierungssysteme eine technische Maßnahme in der IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Sichern Identität"}, {"text": "Nein", "correct": false, "because": "Sie sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Authentifizierungssysteme?', 3, '[{"text": "Identität von Nutzern überprüfen", "correct": true, "because": "Verhindert unbefugten Zugriff"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Authentifizierungssysteme schützen vor Identitätsdiebstahl. b) Sie sind nur für lokale Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Netzwerke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gehören zu Authentifizierungssystemen?', 4, '[{"text": "Passwörter", "correct": true, "because": "Wissen"}, {"text": "Unklare Methoden", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Biometrie", "correct": true, "because": "Besitz"}, {"text": "Smartcards", "correct": true, "because": "Besitz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System ohne Authentifizierungssysteme sicher sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zugriff unsicher"}, {"text": "Ja", "correct": false, "because": "Risiko erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Authentifizierungssysteme?', 3, '[{"text": "Sicherstellen berechtigter Zugriffe", "correct": true, "because": "Schützt System"}, {"text": "Datenverfügbarkeit", "correct": false, "because": "Anderes Ziel"}, {"text": "Datenmanipulation", "correct": false, "because": "Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Authentifizierungssysteme nur für Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Systeme"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Passwort in Authentifizierungssystemen?', 3, '[{"text": "Identität des Nutzers bestätigen", "correct": true, "because": "Wissensbasierte Prüfung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk beschleunigen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zwei-Faktor-Authentifizierung erhöht Sicherheit. b) Passwörter sind immer sicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schwächen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Authentifizierungssysteme?', 3, '[{"text": "Unbefugte können zugreifen", "correct": true, "because": "Schutz fehlt"}, {"text": "Systeme schneller", "correct": false, "because": "Unsinn"}, {"text": "Daten sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Authentifizierung ohne Passwörter erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Biometrie möglich"}, {"text": "Nein", "correct": false, "because": "Alternativen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Authentifizierungssystem?', 3, '[{"text": "Login mit PIN und Fingerabdruck", "correct": true, "because": "Konkret und real"}, {"text": "Daten löschen", "correct": false, "because": "Keine Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Authentifizierung nur für externe Nutzer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Nutzer"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Authentifizierungssysteme?', 4, '[{"text": "Identitätsprüfung", "correct": true, "because": "Kernfunktion"}, {"text": "Unklare Methoden", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Mehrfaktoroptionen", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Zugriffskontrolle", "correct": true, "because": "Beschränkt Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Authentifizierungssysteme dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode erhöht die Sicherheit eines Authentifizierungssystems?', 3, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Doppelte Prüfung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Passwort abschaffen", "correct": false, "because": "Nicht allein ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Authentifizierungssystem ohne Hardware arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Hardware für Zugriff nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gefährdet Authentifizierungssysteme?', 3, '[{"text": "Schwache Passwörter", "correct": true, "because": "Leicht zu knacken"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Authentifizierungssysteme schützen sensible Daten. b) Sie sind nur für Software relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Authentifizierungssystemen?', 3, '[{"text": "Schutz vor unbefugtem Zugriff", "correct": true, "because": "Sichert System"}, {"text": "Maximale Unsicherheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Zugriffskontrolle", "correct": false, "because": "Fördert Sicherheit"}]');
